package io.knowledgebrain.collaboration;
import java.util.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import org.springframework.mock.web.MockHttpServletRequest;import org.springframework.web.server.ResponseStatusException;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
class SubmissionReviewApiTest {
 SubmissionApiTest f;SubmissionReviewStore store;SubmissionReviewController api;
 @BeforeEach void setup(){f=new SubmissionApiTest();f.setup();store=mock(SubmissionReviewStore.class);api=new SubmissionReviewController(store,f.f.api,new SimpleMeterRegistry());}
 org.springframework.http.ResponseEntity<?> get(MockHttpServletRequest r)throws Exception{return api.list(f.f.group.toString(),f.study.toString(),f.assignment.toString(),r);}
 void status(int code,org.junit.jupiter.api.function.Executable action){assertEquals(code,assertThrows(ResponseStatusException.class,action).getStatusCode().value());}
 @Test void currentOwnerReadsDefaultNoStoreWithoutWriteOrigin()throws Exception{when(store.list(f.f.group,f.f.space,f.study,f.assignment,null,20,"ALL")).thenReturn(new SubmissionReviewStore.Page(List.of(),null));var r=f.req("GET",null);r.removeHeader("Origin");var response=get(r);assertEquals("no-store",response.getHeaders().getCacheControl());verify(store).list(f.f.group,f.f.space,f.study,f.assignment,null,20,"ALL");}
 @Test void memberAndViewerCannotReadAnyFilterEvenEmptyQueue(){for(var role:List.of("MEMBER","VIEWER")){f.f.role(role);for(var filter:SubmissionReviewStore.FILTERS){var r=f.req("GET",null);r.addParameter("filter",filter);status(403,()->get(r));}}verifyNoInteractions(store);}
 @Test void exactFiltersAndBoundedCursorArePassedToStore()throws Exception{for(var filter:SubmissionReviewStore.FILTERS){var r=f.req("GET",null);r.addParameter("filter",filter);r.addParameter("after",f.f.id.toString());r.addParameter("limit","100");get(r);verify(store).list(f.f.group,f.f.space,f.study,f.assignment,f.f.id,100,filter);}}
 @Test void malformedQuerySelectorsDuplicateFieldsAndReadBodiesNeverReachStore(){for(var filter:List.of("all","","NEEDS_FEEDBACK,HAS_FEEDBACK","NEEDS_FEEDBACK' OR TRUE--")){var r=f.req("GET",null);r.addParameter("filter",filter);status(400,()->get(r));}for(var limit:List.of("0","101","01","1.0")){var r=f.req("GET",null);r.addParameter("limit",limit);status(400,()->get(r));}var duplicate=f.req("GET",null);duplicate.addParameter("filter","ALL","HAS_FEEDBACK");status(400,()->get(duplicate));var selector=f.req("GET",null);selector.addParameter("authorId",f.f.actor.toString());status(400,()->get(selector));var cursor=f.req("GET",null);cursor.addParameter("after",f.f.id.toString().toUpperCase());status(400,()->get(cursor));status(400,()->get(f.req("GET","{}")));var large=f.req("GET",null);large.setQueryString("x".repeat(257));status(400,()->get(large));verifyNoInteractions(store);}
 @Test void secureSingletonCredentialAndFreshGroupGrantAreRequired(){var insecure=f.req("GET",null);insecure.setSecure(false);var duplicate=f.req("GET",null);duplicate.addHeader("Cookie","__Host-brain_guest="+f.f.token);for(var r:List.of(insecure,duplicate))assertThrows(ResponseStatusException.class,()->get(r));verifyNoInteractions(f.f.auth,store);when(f.f.auth.participation(any(),anyList(),anyString())).thenReturn(new GroupSpaceClient.Access(f.f.actor,"REGISTERED",List.of()));status(404,()->get(f.req("GET",null)));verifyNoInteractions(store);}
}
